:root {
  --ink: #19333a;
  --muted: #658087;
  --surface: #ffffff;
  --accent: #4bc9a7;
  --track: #dce8e6;
}

.charger-card {
  width: 440px;
  padding: 16px;
  background: var(--surface);
  border: 1px solid var(--ink);
  border-radius: 14px;
}

.card-header,
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  color: var(--ink);
  font-size: 21px;
  line-height: 1.1;
}

.battery-icon {
  margin: 0;
  padding: 7px 10px;
  color: var(--ink);
  background: var(--accent);
  border-radius: 8px;
  font-size: 14px;
  font-weight: 700;
}

.charge-bar {
  height: 10px;
  margin: 18px 0 14px;
  overflow: hidden;
  background: var(--track);
  border-radius: 999px;
}

.charge-fill {
  display: block;
  width: 82%;
  height: 100%;
  background: var(--accent);
  border-radius: inherit;
}

.card-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

button {
  padding: 7px 12px;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--ink);
  border-radius: 7px;
  font-size: 13px;
  font-weight: 700;
}
